package glitch

import data.glitch_lib

# Set of weak encryption algorithm names and patterns (including MD5 crypt and SHA1)
weak_algorithms := {"DES", "3DES", "DESEDE", "RC2", "RC4", "ARC4", "ARCFOUR", "MD4", "MD5", "SHA1", "md5_crypt", "ssl", "tls"}

# Set of insufficient key lengths (as integers or strings)
insufficient_key_lengths := {1024, 128, 112, 56, 160}

# Set of weak cipher modes
weak_modes := {"ECB"}

# Function to check if a string value matches a weak algorithm pattern
check_algorithm(value) {
    value.ir_type == "String"
    algorithm := lower(value.value)
    regex.match("(?i).*(DES|3DES|DESEDE|RC2|RC4|ARC4|ARCFOUR|MD4|MD5|SHA1|md5_crypt|ssl|tls).*", algorithm)
} else {
    value.ir_type == "FunctionCall"
    algorithm := lower(value.name)
    regex.match("(?i).*(hash|md5|sha1|ssl|tls).*", algorithm)
} else {
    value.ir_type == "Access"
    check_algorithm(value.left)
}

# Function to check if a value represents an insufficient key length
check_key_length(value) {
    value.ir_type == "Integer"
    insufficient_key_lengths[value.value]
} else {
    value.ir_type == "String"
    key_val := to_number(value.value)
    insufficient_key_lengths[key_val]
} else {
    value.ir_type == "Access"
    check_key_length(value.left)
}

# Function to check if a value represents a weak mode
check_mode(value) {
    value.ir_type == "String"
    mode := lower(value.value)
    mode == "ecb"
} else {
    value.ir_type == "Access"
    check_mode(value.left)
}

# Rule to detect weak encryption algorithms in AtomicUnits (e.g., Ansible shell commands)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for algorithm attributes or command arguments
    attr.name == "algorithm"
    check_algorithm(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Use of weak encryption algorithm - Cryptographic algorithms with insufficient strength can be broken with modern computing power. (CWE-326)"
    }
}

# Rule to detect insufficient key lengths in Variables (e.g., Chef attributes)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    vars := glitch_lib.all_variables(parent)
    node := vars[_]

    # Check for key length attributes in variable names
    regex.match("(?i).*key_size|key_length|bits.*", node.name)
    check_key_length(node.value)

    result := {
        "type": "sec_weak_crypt",
        "element": node,
        "path": parent.path,
        "description": "Insufficient key length - Using keys that are too short makes encryption vulnerable to brute-force attacks. (CWE-326)"
    }
}

# Rule to detect weak encryption algorithms in Variables (e.g., Ansible vars_prompt encrypt attribute)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
