        "element": node,
        "path": parent.path,
        "description": "Use of weak encryption algorithm - Cryptographic algorithms with insufficient strength can be broken with modern computing power. (CWE-326)"
    }
}

# Rule to detect weak cipher modes in Variables (e.g., Chef attributes)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    vars := glitch_lib.all_variables(parent)
    node := vars[_]

    # Check for mode attributes in variable names
    regex.match("(?i).*mode.*", node.name)
    check_mode(node.value)

    result := {
        "type": "sec_weak_crypt",
        "element": node,
        "path": parent.path,
        "description": "Use of weak cipher mode - ECB mode preserves patterns in plaintext, making it insecure. (CWE-326)"
    }
}

# Rule to detect hardcoded static secrets (e.g., passwords) in Variables
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    vars := glitch_lib.all_variables(parent)
    node := vars[_]

    # Check for password/secret attributes in variable names
    regex.match("(?i).*password|secret.*", node.name)
    node.value.ir_type == "String"
    # Check for common static passwords
    regex.match("(?i)^(cassandra|foo|bar|password|123456)$", node.value.value)

    result := {
        "type": "sec_weak_crypt",
        "element": node,
        "path": parent.path,
        "description": "Hardcoded or static secret - Using static passwords weakens encryption. (CWE-326)"
    }
}

